package main

import "testing"

// KeePass KDBX 4 (Argon2d) — validated against a real vault generated with
// pykeepass (password "hashsmith", Argon2d M=64MiB t=14 p=2).
func TestKeePassKDBX4(t *testing.T) {
	h := "$keepass$*4*d*14*67108864*2*19*7264517c7aa1a76af9eaaf503768d2a51e5844430388731829035994b06a7618*a449a3fb4f23e8ffe80051c585e348a78be1dee3801bd6b93dd919d43ae8bc66**85bb3e19b1c5ac2e1ffb9ebdbdf1b549e42e5de2776668ea29a26ff428d60422"
	if ok, err := verifyKeePass(h, "hashsmith"); err != nil || !ok {
		t.Errorf("KDBX4 verify failed: ok=%v err=%v", ok, err)
	}
	if ok, _ := verifyKeePass(h, "wrong"); ok {
		t.Error("KDBX4 should reject the wrong passphrase")
	}
}
